function reconcileCI(payload):
  classRule = getIdentificationRule(payload.className)
  candidates = findCandidatesByCriterion(classRule, payload.identifiers)
  if length(candidates) == 0:
    return insertCI(payload)
  elif length(candidates) == 1:
    return updateCIWithPrecedence(candidates[0], payload)
  else:
    createDeduplicationTask(candidates, payload)
    return candidates[0]

function checkoutCredential(clientCert, clientIp, safeName, targetId):
  if not pkiValidator.verify(clientCert) or not ipWhitelist.contains(clientIp):
    auditLog.emit('UNAUTHORIZED_ACCESS', clientIp)
    throw SecurityException('Forbidden')
  secret = backendVault.retrieve(safeName, targetId)
  auditLog.emit('CHECKOUT_SUCCESS', clientIp, targetId)
  return encryptInTransit(secret, clientCert)

function onCiMutation(ciSysId, eventType, attributes):
  if attributes.isHardware:
    syncHardwareAsset(ciSysId, attributes.serialNumber, attributes.modelId)
  if attributes.hasSoftwareInstalls:
    for sw in attributes.softwareList:
      if not isContainerWorkload(sw):
        normalized = contentService.normalize(sw.rawString)
        persistSwInstall(ciSysId, normalized)
    triggerLicenseReconciliation()
